<script>
	/**
	 * Responsive photo served from /static/images (generated by `npm run images`).
	 * @type {{ name: string; alt: string; sizes?: string; eager?: boolean; class?: string }}
	 */
	let { name, alt, sizes = '(min-width: 960px) 960px, 100vw', eager = false, class: cls = '' } = $props();
</script>

<img
	class="graded {cls}"
	src="/images/{name}-1600.jpg"
	srcset="/images/{name}-800.jpg 800w, /images/{name}-1600.jpg 1600w, /images/{name}-2400.jpg 2400w"
	{sizes}
	{alt}
	width="1600"
	height="1200"
	loading={eager ? 'eager' : 'lazy'}
	fetchpriority={eager ? 'high' : 'auto'}
	decoding="async"
/>
